import { z } from 'zod';

import { LocationId, SuspectId, TimeSlotId, WeaponId } from './ids.js';
import { CaseIssueCode } from './errors.js';
import type { CaseFile } from './case-file.js';

/**
 * A player's guess — shape only.
 * Whether it is CORRECT is the engine's scoring job; shared only checks well-formedness.
 *
 * caseId binds the accusation to a specific case (A1a).
 * accusedSuspectId: SuspectId brand means the victim (VictimId) cannot be accused at compile time.
 */
export const Accusation = z.object({
  caseId: z.string().min(1),
  accusedSuspectId: SuspectId,
  weaponId: WeaponId.optional(),
  locationId: LocationId.optional(),
  timeSlotId: TimeSlotId.optional(),
});
export type Accusation = z.infer<typeof Accusation>;

/** Result of validateAccusation — well-formedness only, never correctness/scoring. */
export interface AccusationValidity {
  ok: boolean;
  issues: CaseIssueCode[];
}

/**
 * Validates that an Accusation is well-formed against a given CaseFile.
 * Checks A1a–A1e. Returns { ok: true, issues: [] } when all pass.
 *
 * NOT a scoring function — it does NOT check whether the accusation matches the solution.
 */
export function validateAccusation(cf: CaseFile, acc: Accusation): AccusationValidity {
  const issues: CaseIssueCode[] = [];

  // A1a: accusation must target the correct case
  if (acc.caseId !== cf.id) {
    issues.push(CaseIssueCode.ACCUSATION_CASE_MISMATCH);
  }

  // A1b: accusedSuspectId must be a known suspect
  const suspectIds = new Set(cf.suspects.map((s) => s.id as string));
  if (!suspectIds.has(acc.accusedSuspectId)) {
    issues.push(CaseIssueCode.ACCUSED_NOT_SUSPECT);
  }

  // A1c: optional weaponId must resolve
  if (acc.weaponId !== undefined) {
    const weaponIds = new Set(cf.weapons.map((w) => w.id as string));
    if (!weaponIds.has(acc.weaponId)) {
      issues.push(CaseIssueCode.ACCUSED_WEAPON_RESOLVES);
    }
  }

  // A1d: optional locationId must resolve
  if (acc.locationId !== undefined) {
    const locationIds = new Set(cf.locations.map((l) => l.id as string));
    if (!locationIds.has(acc.locationId)) {
      issues.push(CaseIssueCode.ACCUSED_LOCATION_RESOLVES);
    }
  }

  // A1e: optional timeSlotId must resolve
  if (acc.timeSlotId !== undefined) {
    const timeSlotIds = new Set(cf.timeline.map((t) => t.id as string));
    if (!timeSlotIds.has(acc.timeSlotId)) {
      issues.push(CaseIssueCode.ACCUSED_TIMESLOT_RESOLVES);
    }
  }

  return { ok: issues.length === 0, issues };
}

src/refinements.ts.source:
/**
 * checkCaseInvariants — all cross-entity CaseFile refinements (R1a–R16).
 *
 * Zod superRefine API note (pinned against zod ^3.24):
 *   ctx.addIssue({ code: z.ZodIssueCode.custom, path: [...], message: '...' })
 *   z.ZodIssueCode.custom === 'custom'
 *
 * Branch-structuring rule: every helper uses collect-violations → if (any) addIssue,
 * so both the "all-present/silent" arm and the "one-missing/fires" arm are independently
 * reachable by the test fixtures.
 */
import { z } from 'zod';

import type { Dossier } from './dossier.js';
import type { Clue } from './clue.js';
import type { SolutionGraph } from './solution-graph.js';
import type { VictimId, WeaponId, LocationId, TimeSlotId, ClueId } from './ids.js';
import { CaseIssueCode } from './errors.js';

// ---------------------------------------------------------------------------
// Local shape of the raw CaseFile value — mirrors case-file.ts without importing it
// (avoids a circular runtime dependency; kept in sync with the z.object there).
// ---------------------------------------------------------------------------
type RawCatalogItem<Id> = { id: Id; label?: string; name?: string; order?: number };

type RawCaseFile = {
  id: string;
  victim: { id: VictimId; name: string };
  weapons: Array<RawCatalogItem<WeaponId>>;
  locations: Array<RawCatalogItem<LocationId>>;
  timeline: Array<{ id: TimeSlotId; label: string; order: number }>;
  suspects: Array<Dossier>;
  clues: Array<Clue>;
  solution: SolutionGraph;
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function addIssue(ctx: z.RefinementCtx, code: CaseIssueCode, path: (string | number)[]): void {
  ctx.addIssue({
    code: z.ZodIssueCode.custom,
    path,
    message: code,
  });
}

/** Collect duplicate ids from an array; return paths of duplicates. */
function findDuplicateIds<T extends { id: string }>(
  items: T[],
  prefix: string,
): Array<[string, number]> {
  const seen = new Set<string>();
  const dupes: Array<[string, number]> = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item === undefined) continue;
    if (seen.has(item.id)) {
      dupes.push([prefix, i]);
    } else {
      seen.add(item.id);
    }
  }
  return dupes;
}

function buildIdSet<T extends { id: string }>(items: T[]): Set<string> {
  return new Set(items.map((x) => x.id));
}

// ---------------------------------------------------------------------------
// checkCaseInvariants — attached via CaseFile.superRefine
// ---------------------------------------------------------------------------

export function checkCaseInvariants(val: RawCaseFile, ctx: z.RefinementCtx): void {
  const suspectIds = buildIdSet(val.suspects);
  const weaponIds = buildIdSet(val.weapons);
  const locationIds = buildIdSet(val.locations);
  const timeSlotIds = buildIdSet(val.timeline);
  const clueIds = buildIdSet(val.clues);

  // -------------------------------------------------------------------------
  // R1a–R1e: uniqueness of catalog ids
  // -------------------------------------------------------------------------

  for (const [prefix, idx] of findDuplicateIds(val.suspects, 'suspects')) {
    addIssue(ctx, CaseIssueCode.DUP_SUSPECT_ID, [prefix, idx, 'id']);
  }
  for (const [prefix, idx] of findDuplicateIds(val.weapons, 'weapons')) {
    addIssue(ctx, CaseIssueCode.DUP_WEAPON_ID, [prefix, idx, 'id']);
  }
  for (const [prefix, idx] of findDuplicateIds(val.locations, 'locations')) {
    addIssue(ctx, CaseIssueCode.DUP_LOCATION_ID, [prefix, idx, 'id']);
  }
  for (const [prefix, idx] of findDuplicateIds(val.timeline, 'timeline')) {
    addIssue(ctx, CaseIssueCode.DUP_TIMESLOT_ID, [prefix, idx, 'id']);
  }
  for (const [prefix, idx] of findDuplicateIds(val.clues, 'clues')) {
    addIssue(ctx, CaseIssueCode.DUP_CLUE_ID, [prefix, idx, 'id']);
  }

  // -------------------------------------------------------------------------
  // R2: exactly one suspect with role === 'culprit'
  // -------------------------------------------------------------------------

  const culprits = val.suspects.filter((s) => s.role === 'culprit');
  if (culprits.length !== 1) {
    addIssue(ctx, CaseIssueCode.EXACTLY_ONE_CULPRIT, ['suspects']);
  }

  // -------------------------------------------------------------------------
  // R3: isGuilty ⟺ role === 'culprit' for every suspect
  // -------------------------------------------------------------------------

  for (let i = 0; i < val.suspects.length; i++) {
    const s = val.suspects[i];
    if (s === undefined) continue;
    const coherent = s.isGuilty === (s.role === 'culprit');
    if (!coherent) {
      addIssue(ctx, CaseIssueCode.GUILT_ROLE_COHERENT, ['suspects', i, 'isGuilty']);
    }
  }

  // -------------------------------------------------------------------------
  // R4: victim.id must not also be a suspect id
  // -------------------------------------------------------------------------

  if (suspectIds.has(val.victim.id)) {
    addIssue(ctx, CaseIssueCode.VICTIM_NOT_SUSPECT, ['victim', 'id']);
  }

  // -------------------------------------------------------------------------
  // R5a: solution.killerId resolves to a known suspect
  // R5b: that suspect has role === 'culprit'
  // -------------------------------------------------------------------------

  if (!suspectIds.has(val.solution.killerId)) {
    addIssue(ctx, CaseIssueCode.KILLER_RESOLVES, ['solution', 'killerId']);
  } else {
    const killer = val.suspects.find((s) => s.id === val.solution.killerId);
    if (killer !== undefined && killer.role !== 'culprit') {
      addIssue(ctx, CaseIssueCode.KILLER_IS_CULPRIT, ['solution', 'killerId']);
    }
  }

  // -------------------------------------------------------------------------
  // R6a: solution.victimId === victim.id  (equality, not .some)
  // R6b–R6d: weapon/location/timeSlot resolve against catalogs
  // -------------------------------------------------------------------------

  if (val.solution.victimId !== val.victim.id) {
    addIssue(ctx, CaseIssueCode.SOLUTION_VICTIM_MATCHES, ['solution', 'victimId']);
  }
  if (!weaponIds.has(val.solution.weaponId)) {
    addIssue(ctx, CaseIssueCode.SOLUTION_WEAPON_RESOLVES, ['solution', 'weaponId']);
  }
  if (!locationIds.has(val.solution.locationId)) {
    addIssue(ctx, CaseIssueCode.SOLUTION_LOCATION_RESOLVES, ['solution', 'locationId']);
  }
  if (!timeSlotIds.has(val.solution.timeSlotId)) {
    addIssue(ctx, CaseIssueCode.SOLUTION_TIMESLOT_RESOLVES, ['solution', 'timeSlotId']);
  }

  // -------------------------------------------------------------------------
  // Per-suspect invariants (R7–R10, R11, R12, R16)
  // -------------------------------------------------------------------------

  for (let si = 0; si < val.suspects.length; si++) {
    const s = val.suspects[si];
    if (s === undefined) continue;

    const knowsSet = new Set(s.knowledge.knows);
    const knownFactsSet = new Set(s.knownFacts);

    // R7: knows ∩ doesNotKnow === ∅
    const knowledgeViolations: number[] = [];
    for (let ki = 0; ki < s.knowledge.doesNotKnow.length; ki++) {
      const fact = s.knowledge.doesNotKnow[ki];
      if (fact !== undefined && knowsSet.has(fact)) {
        knowledgeViolations.push(ki);
      }
    }
    for (const ki of knowledgeViolations) {
      addIssue(ctx, CaseIssueCode.KNOWLEDGE_DISJOINT, [
        'suspects',
        si,
        'knowledge',
        'doesNotKnow',
        ki,
      ]);
    }

    // R8: knownFacts ⊆ knows
    const knownFactsViolations: number[] = [];
    for (let kfi = 0; kfi < s.knownFacts.length; kfi++) {
      const fact = s.knownFacts[kfi];
      if (fact !== undefined && !knowsSet.has(fact)) {
        knownFactsViolations.push(kfi);
      }
    }
    for (const kfi of knownFactsViolations) {
      addIssue(ctx, CaseIssueCode.KNOWN_FACTS_SUBSET, ['suspects', si, 'knownFacts', kfi]);
    }

    // R9: each secret.fact ∈ knows ∧ ∉ knownFacts
    for (let seci = 0; seci < s.secrets.length; seci++) {
      const sec = s.secrets[seci];
      if (sec === undefined) continue;
      if (!knowsSet.has(sec.fact)) {
        addIssue(ctx, CaseIssueCode.SECRET_FACT_COHERENT, [
          'suspects',
          si,
          'secrets',
          seci,
          'fact',
        ]);
      } else if (knownFactsSet.has(sec.fact)) {
        addIssue(ctx, CaseIssueCode.SECRET_FACT_COHERENT, [
          'suspects',
          si,
          'secrets',
          seci,
          'fact',
        ]);
      }
    }

    // R10a: relationship.to resolves to suspects[]∪{victim.id}
    // R10b: no self-edge (to !== owning suspect's id)
    const validPersonIds = new Set([...suspectIds, val.victim.id]);
    for (let ri = 0; ri < s.relationships.length; ri++) {
      const rel = s.relationships[ri];
      if (rel === undefined) continue;
      if (!validPersonIds.has(rel.to)) {
        addIssue(ctx, CaseIssueCode.RELATIONSHIP_TARGET_RESOLVES, [
          'suspects',
          si,
          'relationships',
          ri,
          'to',
        ]);
      }
      if (rel.to === s.id) {
        addIssue(ctx, CaseIssueCode.RELATIONSHIP_NO_SELF_EDGE, [
          'suspects',
          si,
          'relationships',
          ri,
          'to',
        ]);
      }
    }

    // R11: clue-presented leakTriggers resolve against clues[]
    for (let seci = 0; seci < s.secrets.length; seci++) {
      const sec = s.secrets[seci];
      if (sec === undefined) continue;
      if (sec.leakTrigger.kind === 'clue-presented' && !clueIds.has(sec.leakTrigger.clueId)) {
        addIssue(ctx, CaseIssueCode.SECRET_TRIGGER_RESOLVES, [
          'suspects',
          si,
          'secrets',
          seci,
          'leakTrigger',
          'clueId',
        ]);
      }
    }

    // R12: alibi.breaksWhen (when present, clue-presented) clueId resolves
    const bw = s.alibi.breaksWhen;
    if (bw !== undefined && bw.kind === 'clue-presented' && !clueIds.has(bw.clueId)) {
      addIssue(ctx, CaseIssueCode.ALIBI_TRIGGER_RESOLVES, [
        'suspects',
        si,
        'alibi',
        'breaksWhen',
        'clueId',
      ]);
    }

    // R16: culprit's alibi must have breaksWhen (the lie must be breakable)
    if (s.role === 'culprit' && s.alibi.breaksWhen === undefined) {
      addIssue(ctx, CaseIssueCode.CULPRIT_ALIBI_BREAKABLE, ['suspects', si, 'alibi']);
    }
  }

  // -------------------------------------------------------------------------
  // R13a–R13d: clue refersTo cross-checks
  // -------------------------------------------------------------------------

  for (let ci = 0; ci < val.clues.length; ci++) {
    const clue = val.clues[ci];
    if (clue === undefined || clue.refersTo === undefined) continue;

    const rt = clue.refersTo;
    if (rt.suspectId !== undefined && !suspectIds.has(rt.suspectId)) {
      addIssue(ctx, CaseIssueCode.CLUE_REFS_SUSPECT_RESOLVES, [
        'clues',
        ci,
        'refersTo',
        'suspectId',
      ]);
    }
    if (rt.weaponId !== undefined && !weaponIds.has(rt.weaponId)) {
      addIssue(ctx, CaseIssueCode.CLUE_REFS_WEAPON_RESOLVES, ['clues', ci, 'refersTo', 'weaponId']);
    }
    if (rt.locationId !== undefined && !locationIds.has(rt.locationId)) {
      addIssue(ctx, CaseIssueCode.CLUE_REFS_LOCATION_RESOLVES, [
        'clues',
        ci,
        'refersTo',
        'locationId',
      ]);
    }
    if (rt.timeSlotId !== undefined && !timeSlotIds.has(rt.timeSlotId)) {
      addIssue(ctx, CaseIssueCode.CLUE_REFS_TIMESLOT_RESOLVES, [
        'clues',
        ci,
        'refersTo',
        'timeSlotId',
      ]);
    }
  }

  // -------------------------------------------------------------------------
  // R14: at least one non-culprit suspect (one-suspect case is unsolvable)
  // -------------------------------------------------------------------------

  const nonCulprits = val.suspects.filter((s) => s.role !== 'culprit');
  if (nonCulprits.length === 0) {
    addIssue(ctx, CaseIssueCode.WITNESS_OR_HERRING_PRESENT, ['suspects']);
  }

  // -------------------------------------------------------------------------
  // R15: timeline[].order values all distinct
  // -------------------------------------------------------------------------

  const seenOrders = new Set<number>();
  for (let ti = 0; ti < val.timeline.length; ti++) {
    const slot = val.timeline[ti];
    if (slot === undefined) continue;
    if (seenOrders.has(slot.order)) {
      addIssue(ctx, CaseIssueCode.TIMESLOT_ORDER_UNIQUE, ['timeline', ti, 'order']);
    } else {
      seenOrders.add(slot.order);
    }
  }
}

// Re-export for convenience (accusation.ts uses CaseIssueCode via this module)
export type { ClueId };

src/case-file.ts.source:
import { z } from 'zod';

import { LocationId, TimeSlotId, VictimId, WeaponId } from './ids.js';
import { Dossier } from './dossier.js';
import { Clue } from './clue.js';
import { SolutionGraph } from './solution-graph.js';
import { checkCaseInvariants } from './refinements.js';

/** A named victim (single per case). */
export const Victim = z.object({
  id: VictimId,
  name: z.string().min(1),
});
export type Victim = z.infer<typeof Victim>;

/** A weapon in the finite weapon catalog. */
export const Weapon = z.object({
  id: WeaponId,
  label: z.string().min(1),
});
export type Weapon = z.infer<typeof Weapon>;

/** A location in the finite location catalog. */
export const Location = z.object({
  id: LocationId,
  label: z.string().min(1),
});
export type Location = z.infer<typeof Location>;

/**
 * A time slot in the ordered, finite timeline.
 * `order` values must be unique across the timeline (R15) so the engine can sort.
 */
export const TimeSlot = z.object({
  id: TimeSlotId,
  label: z.string().min(1),
  order: z.number().int().nonnegative(),
});
export type TimeSlot = z.infer<typeof TimeSlot>;

/**
 * The full case envelope — the "finite evidentiary core".
 * Cross-entity referential integrity is enforced in checkCaseInvariants (R1a–R16).
 * suspects[] ARE the dossiers — bijection between dossier and suspect is structural.
 */
export const CaseFile = z
  .object({
    id: z.string().min(1),
    victim: Victim,
    weapons: z.array(Weapon).nonempty(),
    locations: z.array(Location).nonempty(),
    timeline: z.array(TimeSlot).nonempty(),
    /** suspects[] ARE dossiers — no separate cast registry needed. */
    suspects: z.array(Dossier).nonempty(),
    clues: z.array(Clue),
    solution: SolutionGraph,
  })
  .superRefine(checkCaseInvariants);
export type CaseFile = z.infer<typeof CaseFile>;

src/clue.ts.source:
import { z } from 'zod';

import { ClueId, LocationId, SuspectId, TimeSlotId, WeaponId } from './ids.js';
import { ClueReliability } from './enums.js';

/**
 * A piece of evidence in the case.
 * reliability is SERVER-ONLY — misleading clues are red herrings.
 * refersTo cross-references are validated at CaseFile.superRefine (R13a–d).
 *
 * Each ref field is individually optional; the refersTo object itself is optional.
 * No .partial() used — each field is explicitly .optional() per plan note.
 */
export const Clue = z.object({
  id: ClueId,
  statement: z.string().min(1),
  /** SERVER-ONLY */
  reliability: ClueReliability,
  refersTo: z
    .object({
      suspectId: SuspectId.optional(),
      weaponId: WeaponId.optional(),
      locationId: LocationId.optional(),
      timeSlotId: TimeSlotId.optional(),
    })
    .optional(),
});
export type Clue = z.infer<typeof Clue>;

src/dossier.ts.source:
import { z } from 'zod';

import { PersonId, SuspectId } from './ids.js';
import { RelationshipKind, Role } from './enums.js';
import { Trigger } from './trigger.js';

/**
 * A fact the character will not volunteer freely but CAN reveal under a trigger.
 * secret.fact ∈ knowledge.knows ∧ secret.fact ∉ knownFacts  (enforced at CaseFile.superRefine R9)
 * SERVER-ONLY
 */
export const Secret = z.object({
  fact: z.string().min(1),
  leakTrigger: Trigger,
  /** In-character consequence prose if the secret leaks. Kept as prose (not structured) per plan. */
  ifLeaked: z.string().min(1),
});
export type Secret = z.infer<typeof Secret>;

/**
 * The suspect's alibi claim plus the server-authoritative truth.
 * breaksWhen absent ⟹ alibi is unbreakable / genuine.  (never null — exactOptionalPropertyTypes)
 * SERVER-ONLY: truth + breaksWhen
 */
export const Alibi = z
  .object({
    claim: z.string().min(1),
    truth: z.string().min(1),
    breaksWhen: Trigger,
  })
  .partial({ breaksWhen: true });
export type Alibi = z.infer<typeof Alibi>;

/**
 * A directed relationship edge from this suspect to another cast member.
 * `to` is a PersonId (suspect OR victim) — no self-edges; resolved at CaseFile.superRefine R10.
 */
export const Relationship = z.object({
  to: PersonId,
  kind: RelationshipKind,
  descriptor: z.string().min(1),
});
export type Relationship = z.infer<typeof Relationship>;

/**
 * Three-tier knowledge model (resolves F3):
 *   - knows        = the character's full closed world (grounding boundary for engine/api)
 *   - doesNotKnow  = facts explicitly unknown to the character
 *   - knows ∩ doesNotKnow = ∅  (enforced at CaseFile.superRefine R7)
 * SERVER-ONLY
 */
export const Knowledge = z.object({
  knows: z.array(z.string().min(1)),
  doesNotKnow: z.array(z.string().min(1)),
});
export type Knowledge = z.infer<typeof Knowledge>;

/**
 * A suspect's full server-side dossier.
 *
 * Three-tier knowledge semantics:
 *   knownFacts ⊆ knows  (R8)        — freely volunteered subset
 *   secrets[].fact ∈ knows \ knownFacts  (R9) — guarded facts
 *
 * SERVER-ONLY fields: secrets, alibi, knowledge, isGuilty, role
 */
export const Dossier = z.object({
  id: SuspectId,
  publicPersona: z.string().min(1),
  /** Freely-offered facts — the subset of knowledge.knows the character volunteers. */
  knownFacts: z.array(z.string().min(1)),
  secrets: z.array(Secret),
  alibi: Alibi,
  relationships: z.array(Relationship),
  knowledge: Knowledge,
  isGuilty: z.boolean(),
  role: Role,
});
export type Dossier = z.infer<typeof Dossier>;

